import { el, on } from './dom';
import { icon } from './icons';

/**
 * 页面角落常驻的浮动工具条。
 * 拖动条身可以挪位置，轻点条身收起或展开；位置与折叠状态记在本地。
 */

const STORAGE_KEY = 'yueji-guanjia.toolbar';
/** 超过这个位移就当作拖动，而不是点击。 */
const DRAG_THRESHOLD = 6;

interface ToolbarState {
  left: number;
  top: number;
  collapsed: boolean;
}

export interface ToolbarCallbacks {
  on_capture: () => void;
  on_text: () => void;
  on_home: () => void;
}

export interface ToolbarHandle {
  root: HTMLElement;
  /** 挂到容器上，并在有尺寸后校正位置。 */
  mount_into: (parent: HTMLElement) => void;
  destroy: () => void;
}

function load_state(): Partial<ToolbarState> {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? (parsed as Partial<ToolbarState>) : {};
  } catch (error) {
    console.warn('[月季管家] 读取工具条位置失败', error);
    return {};
  }
}

function save_state(state: ToolbarState): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch (error) {
    console.warn('[月季管家] 保存工具条位置失败', error);
  }
}

export function create_toolbar(callbacks: ToolbarCallbacks): ToolbarHandle {
  const saved = load_state();
  let collapsed = saved.collapsed === true;
  let left = typeof saved.left === 'number' ? saved.left : Number.NaN;
  let top = typeof saved.top === 'number' ? saved.top : Number.NaN;

  let suppress_click = false;
  let drag_pointer: number | null = null;
  let drag_start_x = 0;
  let drag_start_y = 0;
  let drag_from_left = 0;
  let drag_from_top = 0;
  let dragging = false;
  let disposers: Array<() => void> = [];

  const grip = el('div', { class: 'yj-toolbar__grip', html: icon('grip', 16), title: '拖动移动，轻点收起' });
  const capture_button = el('button', {
    class: 'yj-toolbar__btn',
    html: icon('camera', 19),
    title: '截图',
    attrs: { type: 'button', 'aria-label': '截图' },
  });
  const text_button = el('button', {
    class: 'yj-toolbar__btn',
    html: icon('bookmark', 19),
    title: '文本收藏',
    attrs: { type: 'button', 'aria-label': '文本收藏' },
  });
  const home_button = el('button', {
    class: 'yj-toolbar__btn yj-toolbar__home',
    html: icon('bud', 20),
    title: '打开月季管家',
    attrs: { type: 'button', 'aria-label': '打开月季管家' },
  });

  const root = el('div', { class: 'yj-toolbar' }, [
    grip,
    capture_button,
    el('div', { class: 'yj-toolbar__divider' }),
    text_button,
    el('div', { class: 'yj-toolbar__divider' }),
    home_button,
  ]);

  function clamp(): void {
    const host = root.parentElement;
    if (!host) return;
    const rect = host.getBoundingClientRect();
    const width = root.offsetWidth;
    const height = root.offsetHeight;
    if (!width || !height) return;
    const margin = 6;
    const max_left = Math.max(margin, rect.width - width - margin);
    const max_top = Math.max(margin, rect.height - height - margin);
    if (!Number.isFinite(left)) left = max_left;
    if (!Number.isFinite(top)) top = Math.round(rect.height * 0.56);
    left = Math.min(Math.max(margin, left), max_left);
    top = Math.min(Math.max(margin, top), max_top);
    root.style.left = `${Math.round(left)}px`;
    root.style.top = `${Math.round(top)}px`;
  }

  function persist(): void {
    save_state({ left, top, collapsed });
  }

  function apply_collapsed(): void {
    root.classList.toggle('is-collapsed', collapsed);
    root.title = collapsed ? '轻点展开' : '';
    requestAnimationFrame(() => {
      clamp();
      persist();
    });
  }

  function on_pointer_down(event: PointerEvent): void {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    drag_pointer = event.pointerId;
    drag_start_x = event.clientX;
    drag_start_y = event.clientY;
    drag_from_left = left;
    drag_from_top = top;
    dragging = false;
    suppress_click = false;
    if (typeof root.setPointerCapture === 'function') root.setPointerCapture(event.pointerId);
  }

  function on_pointer_move(event: PointerEvent): void {
    if (drag_pointer !== event.pointerId) return;
    const dx = event.clientX - drag_start_x;
    const dy = event.clientY - drag_start_y;
    if (!dragging && Math.hypot(dx, dy) < DRAG_THRESHOLD) return;
    dragging = true;
    left = drag_from_left + dx;
    top = drag_from_top + dy;
    clamp();
  }

  function on_pointer_up(event: PointerEvent): void {
    if (drag_pointer !== event.pointerId) return;
    drag_pointer = null;
    if (typeof root.hasPointerCapture === 'function' && root.hasPointerCapture(event.pointerId)) {
      root.releasePointerCapture(event.pointerId);
    }
    if (dragging) {
      suppress_click = true;
      window.setTimeout(() => {
        suppress_click = false;
      }, 0);
      persist();
    } else if (event.target === grip || grip.contains(event.target as Node)) {
      // 轻点拖动条 = 收起或展开。
      collapsed = !collapsed;
      apply_collapsed();
      suppress_click = true;
      window.setTimeout(() => {
        suppress_click = false;
      }, 0);
    }
    dragging = false;
  }

  disposers = [
    on<PointerEvent>(root, 'pointerdown', on_pointer_down),
    on<PointerEvent>(root, 'pointermove', on_pointer_move),
    on<PointerEvent>(root, 'pointerup', on_pointer_up),
    on<PointerEvent>(root, 'pointercancel', on_pointer_up),
    on<Event>(capture_button, 'click', () => {
      if (suppress_click) return;
      callbacks.on_capture();
    }),
    on<Event>(text_button, 'click', () => {
      if (suppress_click) return;
      callbacks.on_text();
    }),
    on<Event>(home_button, 'click', () => {
      if (suppress_click) return;
      callbacks.on_home();
    }),
  ];

  return {
    root,
    mount_into: parent => {
      parent.append(root);
      apply_collapsed();
    },
    destroy: () => {
      for (const dispose of disposers) dispose();
      disposers = [];
      root.remove();
    },
  };
}