/**
 * 月季管家  扩展入口。
 * 等酒馆接口就绪后挂载界面；挂不上只在控制台告警，不影响酒馆本身。
 */
import { info, warn } from './core/log';
import { wait_context } from './tavern/env';
import { create_app, HOST_ID } from './ui/app';

async function boot(): Promise<void> {
  const context = await wait_context();
  if (!context) {
    warn('没有等到酒馆接口，界面未挂载。');
    return;
  }
  if (document.getElementById(HOST_ID)) {
    info('界面已经挂载过了，跳过。');
    return;
  }
  create_app(context);
  info('界面已挂载。');
}

boot().catch(error => {
  warn('挂载界面失败', error);
});